#include <stack>
#include <queue>
#include <iostream>

int main() {
    std::stack<int> s;
    for (int x : {1, 2, 3}) s.push(x);
    std::queue<int> q;
    for (int x : {1, 2, 3}) q.push(x);
    std::cout << s.top() << " " << q.front() << " " << q.back() << "\n";
}

#include <deque>
#include <cstddef>
#include <iostream>

int main() {
    std::deque<int> d{3, 4, 5};
    d.push_front(2);      // O(1): empty slot in the front block
    d.push_front(1);
    d.push_back(6);
    for (std::size_t i = 0; i < d.size(); ++i)
        std::cout << d[i] << (i + 1 < d.size() ? " " : "\n");
    std::cout << d[3] << "\n";   // random access still O(1)
}

#include <queue>
#include <vector>
#include <iostream>

struct Order {
    double price;
    int qty;
};

// comp(a,b) == true means a ranks BELOW b: max-heap on price.
struct BidBetter {
    bool operator()(const Order& a, const Order& b) const {
        return a.price < b.price;
    }
};

int main() {
    std::priority_queue<Order, std::vector<Order>, BidBetter> bids;
    bids.push({100.25, 400});
    bids.push({100.75, 200});
    bids.push({100.50, 900});
    std::cout << "top " << bids.top().price << " x " << bids.top().qty << "\n";
    bids.pop();
    std::cout << "next " << bids.top().price << "\n";
}

#include <queue>
#include <vector>
#include <iostream>

struct Order { double price; int qty; };

int main() {
    auto askBetter = [](const Order& a, const Order& b) {
        return a.price > b.price;      // min-heap: lowest price on top
    };
    std::priority_queue<Order, std::vector<Order>, decltype(askBetter)> asks(askBetter);
    asks.push({100.50, 300});
    asks.push({100.25, 100});
    asks.push({100.75, 200});
    std::cout << "best ask " << asks.top().price << "\n";
}

